# First, let me request demos to understand the pattern
# The instructions say: with no demo pair yet, request_demos first

{"action": "request_demos"}

import os, glob, re

def load():
    d = os.environ['RLM_SESSION_DIR']
    t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')
    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows = [r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
            G[k] = [[int(x) for x in r] for r in rows]
    return G

G = load()
print("Loaded grids:", sorted(G.keys()))
for k in G:
    print(f"\n=== {k} ===")
    for i, row in enumerate(G[k] if k in G else [[6,9,9,9,9,9,9,6,6,6,6,6,6,6,6,6,6,6,6,6,6,6]]):
        print(f"  Row {i}: {row}")

import os, glob, re

def load():
    d = os.environ['RLM_SESSION_DIR']
    t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')
    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows = [r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
            G[k] = [[int(x) for x in r] for r in rows]
    return G

G = load()
print("Loaded grids:", sorted(G.keys()))

import os

d = os.environ['RLM_SESSION_DIR']
base = os.path.dirname(d)
print("Base dir:", base)

for root, dirs, files in os.walk(base):
    for f in files:
        if f.endswith('.jsonl'):
            print(os.path.join(root, f))

# Let me check what files are in the workspace directory
import os
workspace = os.path.join(os.environ['RLM_SESSION_DIR'], '..')
workspace = os.path.dirname(workspace)
print("Workspace:", workspace)

# Search for any files with grid data
for root, dirs, files in os.walk(workspace):
    if '.playground' in root or 'paper' in root:
        for f in files:
            if f.endswith('.json') or f.endswith('.txt'):
                path = os.path.join(root, f)
                try:
                    with open(path, 'r') as file:
                        content = file.read()
                        if '6 9 9' in content or '9 9 6' in content or '1 6 6 6 6' in content:
                            print("Found:", path)
                            print("Content preview:", content[:500])
                except:
                    pass

import os

# Walk up the tree to find the grid content
base = os.environ['RLM_SESSION_DIR']
print("Base:", base)

# Search directories upward for any file containing grid-like content
for root in [base, os.path.dirname(base), os.path.dirname(os.path.dirname(base))]:
    if root not in [os.environ['RLM_SESSION_DIR'], os.path.dirname(os.environ['RLM_SESSION_DIR'])]:
        continue

    for dirpath, dirnames, filenames in os.walk(root):
        if 'paper' not in dirpath:
            continue
        for fname in filenames:
            if 'grid' in fname.lower() or 'demo' in fname.lower() or 'test' in fname.lower():
                fpath = os.path.join(dirpath, fname)
                try:
                    with open(fpath, 'r') as f:
                        content = f.read()
                        if any(c.isdigit() and c in '0123456789' and len([c for c in content if c.isdigit()]) > 500:
                            print("Found:", fpath)
                except Exception as e:
                    pass

import os

# Find the workspace folder
workspace = os.path.dirname(os.path.dirname(os.environ['RLM_SESSION_DIR']))
print("Workspace:", workspace)

# Search for any file with 'Demo' or 'Test' content
for root, dirs, files in os.walk(workspace):
    for fname in files:
        fpath = os.path.join(root, fname)
        try:
            with open(fpath, 'r') as f:
                content = f.read()
                if 'Demo pair' in content or 'Test input' in content or 'Task id:' in content:
                    print("Found:", fpath)
                    print("Content preview:", content[:1000])
        except Exception as e:
            pass

